 1	import type { Booking, Prisma, Room, User } from '@prisma/client';
 2	import { prisma } from '../../db/client.js';
 3	import { BOOKING_ACTIVE } from './schema.js';
 4	
 5	export interface BookingData {
 6	  roomId: string;
 7	  userId: string;
 8	  title: string;
 9	  startsAt: Date;
10	  endsAt: Date;
11	}
12	
13	export interface BookingFilter {
14	  roomId?: string;
15	  userId?: string;
16	  status?: string;
17	  from?: Date;
18	  to?: Date;
19	  limit: number;
20	  offset: number;
21	}
22	
23	export function create(data: BookingData): Promise<Booking> {
24	  return prisma.booking.create({ data });
25	}
26	
27	// An active booking overlaps the interval when it starts before the interval
28	// ends and ends after the interval starts. The interval includes its start and
29	// excludes its end, so bookings that merely touch at a boundary do not overlap.
30	function overlapping(roomId: string, startsAt: Date, endsAt: Date): Prisma.BookingWhereInput {
31	  return {
32	    roomId,
33	    status: BOOKING_ACTIVE,
34	    startsAt: { lt: endsAt },
35	    endsAt: { gt: startsAt },
36	  };
37	}
38	
39	export function findConflict(
40	  roomId: string,
41	  startsAt: Date,
42	  endsAt: Date,
43	  excludeId?: string,
44	): Promise<Booking | null> {
45	  const where = overlapping(roomId, startsAt, endsAt);
46	  return prisma.booking.findFirst({
47	    where: excludeId ? { ...where, id: { not: excludeId } } : where,
48	  });
49	}
50	
51	export function listActiveBetween(roomId: string, from: Date, to: Date): Promise<Booking[]> {
52	  return prisma.booking.findMany({
53	    where: overlapping(roomId, from, to),
54	    orderBy: { startsAt: 'asc' },
55	  });
56	}
57	
58	export function findRoomById(id: string): Promise<Room | null> {
59	  return prisma.room.findUnique({ where: { id } });
60	}
61	
62	export function findUserById(id: string): Promise<User | null> {
63	  return prisma.user.findUnique({ where: { id } });
64	}
65	
66	export function findById(id: string): Promise<Booking | null> {
67	  return prisma.booking.findUnique({ where: { id } });
68	}
69	
70	export function list(filter: BookingFilter): Promise<[Booking[], number]> {
71	  const where: Prisma.BookingWhereInput = {};
72	  if (filter.roomId) where.roomId = filter.roomId;
73	  if (filter.userId) where.userId = filter.userId;
74	  if (filter.status) where.status = filter.status;
75	  if (filter.from) where.startsAt = { gte: filter.from };
76	  if (filter.to) where.endsAt = { lte: filter.to };
77	
78	  return prisma.$transaction([
79	    prisma.booking.findMany({
80	      where,
81	      take: filter.limit,
82	      skip: filter.offset,
83	      orderBy: { startsAt: 'asc' },
84	    }),
85	    prisma.booking.count({ where }),
86	  ]);
87	}
88	
89	export function update(id: string, data: Partial<BookingData>): Promise<Booking> {
90	  return prisma.booking.update({ where: { id }, data });
91	}
92	
93	export function updateStatus(id: string, status: string): Promise<Booking> {
94	  return prisma.booking.update({ where: { id }, data: { status } });
95	}
96	
97	export function remove(id: string): Promise<Booking> {
98	  return prisma.booking.delete({ where: { id } });
99	}

