  it('rejects a patch that moves a booking to a room already taken', async () => {
    const other = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Borealis', capacity: 4 },
    });
    await bookAt(24, 25);
    const moving = await bookAt(24, 25, 'Elsewhere', other.json().id);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${moving.json().id}`,
      payload: { roomId },
    });
    expect(response.statusCode).toBe(409);
  });

  it('rejects a patch that moves a booking into the past', async () => {
    const created = await bookAt(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { startsAt: at(-2), endsAt: at(-1) },
    });
    expect(response.statusCode).toBe(400);
  });

  it('answers 404 when a patch points at a room that does not exist', async () => {
    const created = await bookAt(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { roomId: 'missing' },
    });
    expect(response.statusCode).toBe(404);
  });

  it('offers the whole window when the room has no booking', async () => {
    const response = await availability({ roomId, from: at(24), to: at(28) });
    expect(response.statusCode).toBe(200);
    expect(response.json().slots).toEqual([{ startsAt: at(24), endsAt: at(28) }]);
  });

  it('splits the window around an active booking', async () => {
    await bookAt(25, 26);
    const response = await availability({ roomId, from: at(24), to: at(28) });
    expect(response.json().slots).toEqual([
      { startsAt: at(24), endsAt: at(25) },
      { startsAt: at(26), endsAt: at(28) },
    ]);
  });

  it('frees the slot of a cancelled booking', async () => {
    const created = await bookAt(25, 26);
    await app.inject({ method: 'POST', url: `/bookings/${created.json().id}/cancel` });
    const response = await availability({ roomId, from: at(24), to: at(28) });
    expect(response.json().slots).toEqual([{ startsAt: at(24), endsAt: at(28) }]);
  });

  it('ignores a booking made in another room', async () => {
    const other = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Borealis', capacity: 4 },
    });
    await bookAt(25, 26, 'Elsewhere', other.json().id);
    const response = await availability({ roomId, from: at(24), to: at(28) });
    expect(response.json().slots).toEqual([{ startsAt: at(24), endsAt: at(28) }]);
  });

  it('clips bookings that cross the edges of the window', async () => {
    await bookAt(23, 25, 'Before');
    await bookAt(27, 29, 'After');
    const response = await availability({ roomId, from: at(24), to: at(28) });
    expect(response.json().slots).toEqual([{ startsAt: at(25), endsAt: at(27) }]);
  });

  it('keeps only the slots that fit the requested duration', async () => {
    await bookAt(24.5, 25, 'Short gap maker');
    await bookAt(26, 27, 'Second');
    const response = await availability({
      roomId,
      from: at(24),
      to: at(28),
      durationMinutes: '60',
    });
    expect(response.json().slots).toEqual([
      { startsAt: at(25), endsAt: at(26) },
      { startsAt: at(27), endsAt: at(28) },
    ]);
  });

  it('never offers a slot that has already begun', async () => {
    const before = Date.now();
    const response = await availability({ roomId, from: at(-5), to: at(5) });
    const body = response.json();
    expect(new Date(body.from).getTime()).toBeGreaterThanOrEqual(before);
    expect(body.slots[0].startsAt).toBe(body.from);
  });

  it('answers 404 for availability of a room that does not exist', async () => {
    const response = await availability({ roomId: 'missing', from: at(24), to: at(28) });
    expect(response.statusCode).toBe(404);
    expect(response.json().error.code).toBe('NOT_FOUND');
  });

  it('rejects an availability window that does not end after it starts', async () => {
    const response = await availability({ roomId, from: at(28), to: at(24) });
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('offers a slot that can actually be booked', async () => {
    await bookAt(24, 25);
    const slots = (await availability({ roomId, from: at(23), to: at(28) })).json().slots;
    const free = slots[slots.length - 1];
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: {
        roomId,
        userId,
        title: 'From the offered slot',
        startsAt: free.startsAt,
        endsAt: new Date(Date.parse(free.startsAt) + HOUR).toISOString(),
      },
    });
    expect(response.statusCode).toBe(201);
  });
});
